pub fn EncodingChars(comptime encoding: Encoding) type {
    return struct {

pub fn isNsDecDigit(c: encoding.unit()) bool {
                return (switch (c) {
48...57 => true,
else => false,
});
        }

pub fn isNsHexDigit(c: encoding.unit()) bool {
                return (switch (c) {
48...57, 97...102, 65...70 => true,
else => false,
});
        }

pub fn isNsWordChar(c: encoding.unit()) bool {
                return (switch (c) {
48...57, 65...90, 97...122, '-' => true,
else => false,
});
        }

pub fn isNsChar(c: encoding.unit()) bool {
                return (switch (encoding) {
.utf8 => (switch (c) {
' ', 9 => false,
10, 13 => false,
33...126 => true,
128...255 => true,
else => false,
}),
.utf16 => (switch (c) {
' ', 9 => false,
10, 13 => false,
33...126 => true,
133 => true,
160...55295 => true,
57344...65533 => true,
else => false,
}),
.latin1 => (switch (c) {
' ', 9 => false,
10, 13 => false,
else => true,
}),
});
        }

pub fn isNsTagChar(cs: []const encoding.unit()) ?u8 {
                if ((cs.len == 0)) {
                    return null;
                }
                switch (cs[0]) {
'#', ';', '/', '?', ':', '@', '&', '=', '+', '$', '_', '.', '~', '*', '\'', '(', ')' => {
return 1;
},
'!', ',', '[', ']', '{', '}' => {
return null;
},
else => |c| {
if ((c == 37)) {
                    if ((((cs.len > 2) and @This().isNsHexDigit(cs[1])) and @This().isNsHexDigit(cs[2]))) {
                        return 3;
                    }
                }
                if (@This().isNsWordChar(c)) {
                    return 1;
                }
                return null;
},
}
        }

pub fn isBChar(c: encoding.unit()) bool {
                return ((c == 10) or (c == 13));
        }

pub fn isSWhite(c: encoding.unit()) bool {
                return ((c == 32) or (c == 9));
        }

pub fn isNsPlainSafeOut(c: encoding.unit()) bool {
                return @This().isNsChar(c);
        }

pub fn isNsPlainSafeIn(c: encoding.unit()) bool {
                return (@This().isNsChar(c) and (!@This().isCFlowIndicator(c)));
        }

pub fn isCIndicator(c: encoding.unit()) bool {
                return (switch (c) {
'-', '?', ':', ',', '[', ']', '{', '}', '#', '&', '*', '!', '|', '>', '\'', '"', '%', '@', '`' => true,
else => false,
});
        }

pub fn isCFlowIndicator(c: encoding.unit()) bool {
                return (switch (c) {
',', '[', ']', '{', '}' => true,
else => false,
});
        }

pub fn isNsUriChar(cs: []const encoding.unit()) bool {
                if ((cs.len == 0)) {
                    return false;
                }
                switch (cs[0]) {
'#', ';', '/', '?', ':', '@', '&', '=', '+', '$', ',', '_', '.', '!', '~', '*', '\'', '(', ')', '[', ']' => {
return true;
},
else => |c| {
if ((c == 37)) {
                    if ((((cs.len > 2) and @This().isNsHexDigit(cs[1])) and @This().isNsHexDigit(cs[2]))) {
                        return true;
                    }
                }
                return @This().isNsWordChar(c);
},
}
        }

pub fn isNsAnchorChar(c: encoding.unit()) bool {
                return (@This().isNsChar(c) and (!@This().isCFlowIndicator(c)));
        }
    };
}

