pub fn addToLog(self: ParserParseResultError, source: *const logger.Source, log: *logger.Log) StackOverflowOrOOMError!void {
            switch (self) {
.oom => {
return error.OutOfMemory;
},
.stack_overflow => {
return error.StackOverflow;
},
.unexpected_eof => |e| {
_ = try log.addError(source, e.pos.loc(), "Unexpected EOF");
},
.unexpected_token => |e| {
_ = try log.addError(source, e.pos.loc(), "Unexpected token");
},
.unexpected_character => |e| {
_ = try log.addError(source, e.pos.loc(), "Unexpected character");
},
.tab_indentation => |e| {
_ = try log.addError(source, e.pos.loc(), "Tab characters cannot be used as indentation");
},
.invalid_directive => |e| {
_ = try log.addError(source, e.pos.loc(), "Invalid directive");
},
.unresolved_tag_handle => |e| {
_ = try log.addError(source, e.pos.loc(), "Unresolved tag handle");
},
.unresolved_alias => |e| {
_ = try log.addError(source, e.pos.loc(), "Unresolved alias");
},
.multiline_implicit_key => |e| {
_ = try log.addError(source, e.pos.loc(), "Multiline implicit key");
},
.multiple_anchors => |e| {
_ = try log.addError(source, e.pos.loc(), "Multiple anchors");
},
.multiple_tags => |e| {
_ = try log.addError(source, e.pos.loc(), "Multiple tags");
},
.unexpected_document_start => |e| {
_ = try log.addError(source, e.pos.loc(), "Unexpected document start");
},
.unexpected_document_end => |e| {
_ = try log.addError(source, e.pos.loc(), "Unexpected document end");
},
.multiple_yaml_directives => |e| {
