},
}
    }
};

pub fn ParserParseResult(comptime enc: Encoding) type {
    return union(enum) {
        result: Result,
        @"err": ParseErrUnion,

pub fn success(stream: Stream, parser: *const Parser(enc)) ParserParseResult(enc) {
                return .{ .result = .{ .stream = stream, .allocator = parser.allocator } };
        }

pub fn fail(e: ParseError, parser: *const Parser(enc)) ParserParseResult(enc) {
                if ((e == error.OutOfMemory)) {
                    return .{ .@"err" = .oom };
                } else {
                    if ((e == error.StackOverflow)) {
                        return .{ .@"err" = .stack_overflow };
                    } else {
                        if ((e == error.UnexpectedToken)) {
                            return .{ .@"err" = ParserParseResultError{ .unexpected_token = ParserErrorPos{ .pos = parser.token.start } } };
                        } else {
                            if ((e == error.UnexpectedEof)) {
                                return .{ .@"err" = ParserParseResultError{ .unexpected_eof = ParserErrorPos{ .pos = parser.token.start } } };
                            } else {
                                if ((e == error.TabIndentation)) {
                                    return .{ .@"err" = ParserParseResultError{ .tab_indentation = ParserErrorPos{ .pos = parser.token.start } } };
                                } else {
                                    if ((e == error.InvalidDirective)) {
                                        return .{ .@"err" = ParserParseResultError{ .invalid_directive = ParserErrorPos{ .pos = parser.token.start } } };
                                    } else {
                                        if ((e == error.UnexpectedCharacter)) {
                                            if ((!parser.pos.isLessThan(parser.input.len))) {
                                                return .{ .@"err" = ParserParseResultError{ .unexpected_eof = ParserErrorPos{ .pos = parser.pos } } };
                                            }
                                            return .{ .@"err" = ParserParseResultError{ .unexpected_character = ParserErrorPos{ .pos = parser.pos } } };
                                        } else {
                                            if ((e == error.UnresolvedTagHandle)) {
                                                return .{ .@"err" = ParserParseResultError{ .unresolved_tag_handle = ParserErrorPos{ .pos = parser.pos } } };
                                            } else {
                                                if ((e == error.UnresolvedAlias)) {
                                                    return .{ .@"err" = ParserParseResultError{ .unresolved_alias = ParserErrorPos{ .pos = parser.token.start } } };
                                                } else {
                                                    if ((e == error.MultilineImplicitKey)) {
                                                        return .{ .@"err" = ParserParseResultError{ .multiline_implicit_key = ParserErrorPos{ .pos = parser.token.start } } };
                                                    } else {
                                                        if ((e == error.MultipleAnchors)) {
                                                            return .{ .@"err" = ParserParseResultError{ .multiple_anchors = ParserErrorPos{ .pos = parser.token.start } } };
                                                        } else {
                                                            if ((e == error.MultipleTags)) {
                                                                return .{ .@"err" = ParserParseResultError{ .multiple_tags = ParserErrorPos{ .pos = parser.token.start } } };
                                                            } else {
                                                                if ((e == error.UnexpectedDocumentStart)) {
                                                                    return .{ .@"err" = ParserParseResultError{ .unexpected_document_start = ParserErrorPos{ .pos = parser.pos } } };
                                                                } else {
                                                                    if ((e == error.UnexpectedDocumentEnd)) {
                                                                        return .{ .@"err" = ParserParseResultError{ .unexpected_document_end = ParserErrorPos{ .pos = parser.pos } } };
                                                                    } else {
                                                                        if ((e == error.MultipleYamlDirectives)) {
                                                                            return .{ .@"err" = ParserParseResultError{ .multiple_yaml_directives = ParserErrorPos{ .pos = parser.token.start } } };
                                                                        } else {
                                                                            if ((e == error.InvalidIndentation)) {
                                                                                return .{ .@"err" = ParserParseResultError{ .invalid_indentation = ParserErrorPos{ .pos = parser.pos } } };
                                                                            }
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                return .{ .@"err" = .oom };
        }
        const Stream = ParserStream(enc);
        const ParseError = Parser(enc).ParseError;
        const ParseErrUnion = ParserParseResultError;
        pub const Result = ParserParseResultOk(enc);
        pub const Error = ParserParseResultError;
    };
}

pub const ParserMappingProps = struct {
    #list: bun.collections.ArrayList(G.Property),

pub fn init(allocator: std.mem.Allocator) ParserMappingProps {
            return .{ .#list = .initIn(allocator) };
    }

pub fn merge(self: *ParserMappingProps, merge_props: []const G.Property) OOM!void {
            _ = try self.#list.ensureUnusedCapacity(merge_props.len);
            var iter = std.mem.reverseIterator(merge_props);
            _ = &iter;
            next_merge_prop: while (iter.next()) |merge_prop| {
                const merge_key = merge_prop.key.?;
                for (cp_iter_slice(self.#list.items())) |existing_prop| {
                    _ = &existing_prop;
                    const existing_key = existing_prop.key.?;
                    if (yamlMergeKeyExprEql(existing_key, merge_key)) {
                        continue :next_merge_prop;
                    }
                }
                _ = self.#list.appendAssumeCapacity(merge_prop);
            }
    }

pub fn append(self: *ParserMappingProps, prop: G.Property) OOM!void {
            _ = try self.#list.append(prop);
    }

pub fn appendMaybeMerge(self: *ParserMappingProps, key: Expr, value: Expr) OOM!void {
            if ((switch (key.data) {
.e_string => |key_str| (!key_str.eqlComptime("<<")),
else => true,
})) {
                return self.#list.append(.{ .key = key, .value = value });
            }
            return (switch (value.data) {
.e_object => |value_obj| self.merge(value_obj.properties.slice()),
.e_array => |value_arr| {
for (cp_iter_slice(value_arr.items.slice())) |item| {
                _ = &item;
                const item_obj = (switch (item.data) {
.e_object => |obj| obj,
else => continue,
});
                _ = try self.merge(item_obj.properties.slice());
            }
},
else => self.#list.append(.{ .key = key, .value = value }),
});
    }

pub fn moveList(self: *ParserMappingProps) G.Property.List {
            return bun.BabyList(G.Property).moveFromList((&self.#list));
    }
};

