                const pos = self.pos;
                if (pos.isLessThan(self.input.len)) {
                    return chars.isNsHexDigit(self.input[@as(usize, @intCast(pos.cast()))]);
                }
                return false;
        }

pub fn isNsDecDigit(self: *@This()) bool {
                const pos = self.pos;
                if (pos.isLessThan(self.input.len)) {
                    return chars.isNsDecDigit(self.input[@as(usize, @intCast(pos.cast()))]);
                }
                return false;
        }

pub fn skipNsDecDigits(self: *@This()) void {
                while (self.isNsDecDigit()) {
                    _ = self.inc(1);
