pub fn trySkipNsWordChars(self: *@This()) UnexpectedCharacterError!void {
                if ((!self.isNsWordChar())) {
                    return error.UnexpectedCharacter;
                }
                _ = self.skipNsWordChars();
        }

pub fn isNsUriChar(self: *@This()) bool {
                const r = self.remain();
                return chars.isNsUriChar(r);
        }

pub fn skipNsUriChars(self: *@This()) void {
                while (self.isNsUriChar()) {
                    _ = self.inc(1);
                }
        }

pub fn trySkipNsUriChars(self: *@This()) UnexpectedCharacterError!void {
                if ((!self.isNsUriChar())) {
                    return error.UnexpectedCharacter;
                }
                _ = self.skipNsUriChars();
        }

pub fn stringRange(self: *@This()) String.Range.Start {
                return .{ .off = self.pos, .parser = self };
        }

pub fn stringBuilder(self: *@This()) String.Builder {
                return .{ .parser = self, .str = .{ .range = .{ .off = .zero, .end = .zero } } };
