pub fn Token(comptime encoding: Encoding) type {
    return struct {
        start: Pos,
        indent: Indent,
        line: Line,
        data: Data,

pub fn eof(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .eof };
        }

pub fn sequenceEntry(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .sequence_entry };
        }

pub fn mappingKey(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .mapping_key };
        }

pub fn mappingValue(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .mapping_value };
        }

pub fn collectEntry(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .collect_entry };
        }

pub fn sequenceStart(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .sequence_start };
        }

pub fn sequenceEnd(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .sequence_end };
        }

pub fn mappingStart(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .mapping_start };
        }

pub fn mappingEnd(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .mapping_end };
        }

pub fn anchor(init: AnchorInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .{ .anchor = (if (@typeInfo(@TypeOf(init)) == .@"enum" or @typeInfo(@TypeOf(init)) == .@"union") @tagName(init) else init.name) } };
        }

pub fn alias(init: AliasInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .{ .alias = (if (@typeInfo(@TypeOf(init)) == .@"enum" or @typeInfo(@TypeOf(init)) == .@"union") @tagName(init) else init.name) } };
        }

pub fn tag(init: TagInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .{ .tag = init.tag } };
        }

pub fn directive(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .directive };
        }

pub fn reserved(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .reserved };
        }

pub fn documentStart(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .document_start };
        }

pub fn documentEnd(init: TokenInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .document_end };
        }

pub fn scalar(init: ScalarInit) @This() {
                return .{ .start = init.start, .indent = init.indent, .line = init.line, .data = .{ .scalar = init.resolved } };
        }
        const NodeTag = Parser(encoding).NodeTag;
        const NodeScalar = Parser(encoding).NodeScalar;
        const String = Parser(encoding).String;
        const AnchorInit = TokenAnchorInit(encoding);
        const AliasInit = TokenAliasInit(encoding);
        const TagInit = TokenTagInit(encoding);
        const ScalarInit = TokenScalarInit(encoding);
        pub const Data = TokenData(encoding);
        pub const Scalar = TokenScalar(encoding);
    };
}

