pub fn parse(comptime encoding: Encoding, allocator: std.mem.Allocator, input: []const encoding.unit()) Parser(encoding).ParseResult {
        var parser: Parser(encoding) = .init(allocator, input);
        _ = &parser;
        const stream = (blk_catch_6: { break :blk_catch_6 ((parser.parse()) catch |e| { _ = &e; return Parser(encoding).ParseResult.fail(e, (&parser)); }); });
        return Parser(encoding).ParseResult.success(stream, (&parser));
}

pub fn print(comptime encoding: Encoding, allocator: std.mem.Allocator, stream: Parser(encoding).Stream, writer: anytype) std.Io.Writer.Error!void {
        var printer: Parser(encoding).Printer(@TypeOf(writer)) = .{ .input = stream.input, .stream = stream, .indent = .none, .writer = writer, .allocator = allocator };
        _ = &printer;
        _ = try printer.print();
}

pub fn yamlMergeKeyExprEql(l: Expr, r: Expr) bool {
        if ((std.@"meta".activeTag(l.data) != std.@"meta".activeTag(r.data))) {
            return false;
        }
        return (switch (l.data) {
.e_null => true,
.e_boolean => |l_boolean| ((if (@typeInfo(@TypeOf(l_boolean)) == .@"enum") @intFromEnum(l_boolean) else l_boolean.value) == (if (@typeInfo(@TypeOf(r.data.e_boolean)) == .@"enum") @intFromEnum(r.data.e_boolean) else r.data.e_boolean.value)),
.e_number => |l_number| ((if (@typeInfo(@TypeOf(l_number)) == .@"enum") @intFromEnum(l_number) else l_number.value) == (if (@typeInfo(@TypeOf(r.data.e_number)) == .@"enum") @intFromEnum(r.data.e_number) else r.data.e_number.value)),
.e_string => |l_string| l_string.eql(E.String, r.data.e_string),
.e_array => |l_array| (l_array == r.data.e_array),
.e_object => |l_object| (l_object == r.data.e_object),
else => false,
});
}
